package com.fixflow.mall.service;

import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.repo.OrderRepository;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderService orderService;

    @Test
    @DisplayName("正向测试: 当订单存在且商品ID列表非空时, 应返回第一个商品ID")
    void testFirstItemId_WhenItemIdsNotEmpty_ShouldReturnFirstId() {
        Long orderId = 1L;
        MallOrder order = new MallOrder();
        List<Long> itemIds = new ArrayList<>();
        itemIds.add(100L);
        itemIds.add(200L);
        order.setItemIds(itemIds);

        when(orderRepository.findById(orderId)).thenReturn(Optional.of(order));

        Long result = orderService.firstItemId(orderId);

        assertEquals(100L, result);
    }

    @Test
    @DisplayName("边界测试: 当订单存在但商品ID列表为空时, 应返回null且不抛出异常")
    void testFirstItemId_WhenItemIdsEmpty_ShouldReturnNull() {
        Long orderId = 1L;
        MallOrder order = new MallOrder();
        List<Long> itemIds = Collections.emptyList();
        order.setItemIds(itemIds);

        when(orderRepository.findById(orderId)).thenReturn(Optional.of(order));

        Long result = orderService.firstItemId(orderId);

        assertNull(result);
    }

    @Test
    @DisplayName("空值处理: 当订单存在但商品ID列表为null时, 应返回null且不抛出异常")
    void testFirstItemId_WhenItemIdsNull_ShouldReturnNull() {
        Long orderId = 1L;
        MallOrder order = new MallOrder();
        order.setItemIds(null);

        when(orderRepository.findById(orderId)).thenReturn(Optional.of(order));

        Long result = orderService.firstItemId(orderId);

        assertNull(result);
    }

    @Test
    @DisplayName("异常测试: 当订单不存在时, 应抛出NoSuchElementException")
    void testFirstItemId_WhenOrderNotFound_ShouldThrowException() {
        Long orderId = 1L;
        when(orderRepository.findById(orderId)).thenReturn(Optional.empty());

        assertThrows(NoSuchElementException.class, () -> orderService.firstItemId(orderId));
    }
}
